def find_hollow_boxes(grid, min_size=3):
    """Find hollow rectangular boxes - solid colored borders with different interiors."""
    height, width = len(grid), len(grid[0])
    boxes = []

    # Try all possible box positions and sizes
    for r1 in range(height):
        for c1 in range(width):
            for h in range(min_size, min(height-r1+1, 12)):  # Limit search
                for w in range(min_size, min(width-c1+1, 12)):
                    r2 = r1 + h - 1
                    c2 = c1 + w - 1

                    # Check if this forms a valid hollow box
                    border_color = grid[r1][c1]
                    is_hollow = True

                    # Check all border cells are same color
                    for tr in range(r1, r2+1):
                        for tc in range(c1, c2+1):
                            if tr == r1 or tr == r2 or tc == c1 or tc == c2:
                                if grid[tr][tc] != border_color:
                                    is_hollow = False
                                    break
                        if not is_hollow:
                            break
                    if not is_hollow:
                        continue

                    # Check if there's any non-background interior
                    has_interior = False
                    interior_colors = set()
                    for tr in range(r1+1, r2):
                        for tc in range(c1+1, c2):
                            val = grid[tr][tc]
                            interior_colors.add(val)
                            if val != border_color:
                                has_interior = True

                    if has_interior:
                        boxes.append((r1, r2, c1, c2, border_color))

    return boxes

