def find_maximal_boxes(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    candidates = []

    # Find all potential maximal boxes by scanning grid for border starts
    for r1 in range(rows):
        for c1 in range(cols):
            # Try to grow a box from this corner
            max_h = min(rows - r1, cols - c1)
            if max_h < 4:
                continue

            best = None
            for h in range(4, max_h + 1):
                for w in range(4, cols - c1 + 1):
                    r2, c2 = r1 + h - 1, c1 + w - 1

                    # Check uniform border starting from (r1,c1)
                    border = grid[r1][c1]

                    border_ok = True
                    # Top and bottom edges
                    for c in range(c1, c2 + 1):
                        if grid[r1][c] != border or grid[r2][c] != border:
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Left and right edges (excluding corners already checked)
                    for r in range(r1 + 1, r2):
                        if grid[r][c1] != border or grid[r][c2] != border:
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Check interior is uniform with color 6
                    int_color = None
                    interior_ok = True
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            cell = grid[r][c]
                            if interior_ok and cell != 6:
                                interior_ok = False
                                break
                        if not interior_ok:
                            break

                    if not interior_ok:
                        continue

                    # Valid box found - try to maximize size
                    if best is None or h >= best[1] or (h == best[1] and w >= best[3]):
                        best = (r1, r2, c1, c2, h, w, border, int_color)

            if best:
                candidates.append(best)

    return candidates

